1	import { existsSync, readFileSync } from 'node:fs';
2	import { join } from 'node:path';
3	import { finding } from './findings.mjs';
4	import { parseYaml } from './minimal-yaml.mjs';
5	
6	// The declarative pattern-check engine: a rule whose whole logic is "these
7	// patterns over these files" is DECLARED as data — and data is JSON, not code.
8	// A pack's declarations live in `packs/<pack>/declared-checks.json` (a skill's
9	// in `<pack>/skills/<name>/declared-checks.json`), an array of specs the pack
10	// registry discovers structurally and compiles here into ordinary
11	// `{ id, severity, why, run(ctx) }` rule objects the runner treats like any
12	// other. Nothing wires them: dropping a declaration into the file adds it.
13	//
14	// The format admits no comments — the pattern plus its failureMessage/what/fix
15	// text IS the check — and no prose pointers: a declaration states its own case
16	// or it isn't finished. So a spec carries exactly:
17	//   id              the rule id settings and findings name it by
18	//   severity        'blocking' | 'advisory'
19	//   failureMessage  why this matters, printed on every finding the rule makes
20	//   …the assertions below, each with the `what` and `fix` it fails with
21	//
22	// REGEXES ARE STRINGS in `/body/flags` form — "/^\\s*schedule:/m" — compiled at
23	// load. Keys that accept a path instead (scanFiles, excludeFiles, pathExists)
24	// read any other string as an exact repo path; at every other pattern key a
25	// string that is not in `/…/` form is an authoring error, reported as one.
26	// The engine owns only the walking (the mechanism/policy line line-scanning.mjs
27	// draws): every pattern, file filter, and failure text stays in the declaration.
28	// Spec keys are deliberately wordy — a declaration must read as the whole check
29	// without this header.
30	//
31	// Built for MANY such rules at once: however many pattern rules a run holds,
32	// the engine makes ONE pass over the scanned tree — each file is read once and
33	// its lines split once, with every subscribing rule's assertions evaluated in
34	// that single visit — and the per-context results are cached, so the first
35	// pattern rule the runner reaches pays for the whole family and the rest are
36	// lookups. Regexes must be non-global (`.test` on a /g regex is stateful).
37	//
38	// The spec vocabulary — everything beyond the rule metadata is optional:
39	//   scanFiles          which files the content assertions read: a RegExp over
40	//                      repo paths, or one exact path (read directly)
41	//   scanTracked        true = scan every git-tracked file (mode-independent);
42	//                      default is ctx.files (the run's scanned set —
43	//                      tracked+untracked minus vendored, and only the changed
44	//                      files under --changed)
45	//   excludeFiles       RegExp (or exact path) removing files from scope
46	//   relevantWhen       repo-level relevance, all parts must hold:
47	//                        pathExists / pathAbsent          a path present/absent
48	//                        trackedFileMatches               some tracked path matches
49	//                        noTrackedFileMatches             no tracked path matches
50	//                        exactlyOneTrackedFileMatches     exactly one tracked path matches
51	//                        someTrackedFileContains          { pathMatching, text } — some
52	//                                                         tracked path matching the first
53	//                                                         has text matching the second
54	//                        scanningWholeRepo                true = only under a whole-repo
55	//                                                         sweep (mode 'all'), never a
56	//                                                         --changed run
57	//                        repoContains                     some in-scope file's text
58	//                                                         matches — evaluated only
59	//                                                         if findings exist
60	//   whenMissing        { what, fix } — fires when an exact-path scanFiles is absent
61	//   maxLines           { limit, what, fix } — fires past `limit` lines, anchored there
62	//   skipLinesMatching  RegExp — lines it matches are invisible to matchLines
63	//   matchLines         [{ match, unlessLineMatches, whenFileMatches,
64	//                         unlessFileMatches, what, fix }]
65	//                      flag each line `match` hits (unless `unlessLineMatches`
66	//                      hits it too), in files where every `whenFileMatches`
67	//                      matches and `unlessFileMatches` does not; per line, the
68	//                      first matching assertion wins
69	//   checkEachFile      [{ relevantWhen, whenFileMatches, require, forbid, what, fix }]
70	//                      one finding per file: where every `whenFileMatches`
71	//                      matches, `require` must match / `forbid` must not
72	//                      (`whenFileMatches` takes one RegExp or a list)
73	//   repoWide           [{ unlessSomeFileMatches, flagFilesMatching,
74	//                         neverFlagFiles, what, fix }]
75	//                      unless some in-scope file matches `unlessSomeFileMatches`,
76	//                      flag every file (minus `neverFlagFiles`) satisfying a
77	//                      `flagFilesMatching` group — a list of all-must-match
78	//                      RegExp lists — anchored at the first group's first
79	//                      pattern's first matching line
80	//   requirePaths       [{ path, what, fix }] — each path must exist on disk
81	//   listedInFile       [{ eachTrackedPathMatching, listFile, asText, what, fix }]
82	//                      every tracked path the RegExp matches must appear in
83	//                      `listFile` as the `asText` template (capture groups
84	//                      interpolate); findings anchor on the list file, sorted,
85	//                      and an absent list file asserts nothing
86	//   coveredByGlobLine  [{ eachPathMatching, includeVendored, globFile,
87	//                         globLineMatching, what, fix }]
88	//                      every scanned path the RegExp matches (includeVendored:
89	//                      true widens to ctx.allFiles) must be covered — full path
90	//                      or basename — by the first-token glob of some
91	//                      non-comment `globFile` line matching `globLineMatching`;
92	//                      findings anchor on each uncovered path
93	//
94	// The structured-data assertions read PARSED documents — `.json` via JSON.parse,
95	// `.yaml`/`.yml` via the minimal YAML parser — each file parsed at most once per
96	// scan, shared by every rule; an absent or unparsable document asserts nothing.
97	// A field path is dot-separated (`devDependencies.esbuild`), and a field counts
98	// as present when its value is not undefined:
99	//   checkParsedFile    [{ file, whenFieldPresent, requireField, forbidField,
100	//                         what, fix }]
101	//                      in the parsed document: where `whenFieldPresent` is
102	//                      present, `requireField` must be present / `forbidField`
103	//                      must not
104	//   equalParsedValues  [{ first: { file | filesMatching + whereFileContains,
105	//                                  field },
106	//                         second: { file, field },
107	//                         whenSecondMissing, whenUnequal }]
108	//                      the two parsed fields must be equal; `filesMatching` +
109	//                      `whereFileContains` select the first tracked file whose
110	//                      path and text match; an absent second file fires
111	//                      `whenSecondMissing` at its path, a mismatch fires
112	//                      `whenUnequal` at the first file with {first}/{second}
113	//   forEachParsedEntry [{ inFilesMatching, entriesAtField, whereFieldEquals:
114	//                         { field, equals }, forbidValueInArray: { atField,
115	//                         value, ignoreCase }, what, fix }]
116	//                      in each tracked file matching, for each named entry of
117	//                      the object at `entriesAtField` whose `whereFieldEquals`
118	//                      holds: the array at `atField` must not contain `value`;
119	//                      {entry} interpolates the entry's name
120	//   checkKeyValueFile  [{ file, keys, whenMissing, whenLineNotKeyValue,
121	//                         whenKeyUnknown, whenKeyMissing }]
122	//                      the dotenv-style file must exist, hold only KEY=value
123	//                      lines and # comments, use only the declared keys, and
124	//                      declare every one; {key}/{keys}/{line} interpolate
125	//
126	// The markdown-section assertions read each scanned page's `## ` sections —
127	// headings matched case-insensitively with suffix words allowed, fenced code
128	// blocks invisible, a section running to the next `## ` heading or EOF. A
129	// top-level bullet is a column-0 `-`/`*`/`+` line; a bullet BLOCK is the bullet
130	// plus its indented continuation lines; a DATED bullet leads with its
131	// YYYY-MM-DD run date, bold or plain, validated as a real calendar date. Every
132	// assertion except requirePresent asserts nothing when the section is absent
133	// (presence is its own declared finding, never double-reported):
134	//   checkSections      [{ section | sections: [names], … }] with, each optional:
135	//                        requirePresent                   the `## {section}` heading must exist
136	//                        requireFirstOnPage               no other `## ` heading may precede it
137	//                                                         ({first} = the heading that does)
138	//                        forbidProseLines                 non-bullet, non-continuation lines
139	//                                                         are findings ({line} = the text)
140	//                        eachBulletBlockMatches           { pattern } — every bullet block must match
141	//                        eachBulletLeadsWithDate          { whenUndated, whenNotRealDate } —
142	//                                                         every bullet starts with a real date
143	//                                                         ({date} = the one that isn't)
144	//                        minBullets / maxBullets          { count } — bullet-count floor/ceiling
145	//                                                         ({bullets} = the actual count)
146	//                        maxBulletBlockLength             { characters } — block-length ceiling
147	//                                                         ({characters} = the actual length)
148	//                        newestDatedBulletWithinDays      { days } — the newest dated bullet
149	//                                                         (dates > 2 days in the future
150	//                                                         discarded; clock = ctx.now, wall
151	//                                                         clock otherwise) must be at most
152	//                                                         `days` old ({age}, {date}, {days})
153	//                      {bullet} everywhere = the bullet line's first 80 characters
154	//
155	// `what`/`fix` are templates: `{path}`, a named capture group's `{name}`, and
156	// `{match}` (a matchLines hit's text), `{lines}`/`{limit}` (maxLines) interpolate.
157	
158	const REGISTRY = [];
159	const scans = new WeakMap();
160	
161	const arr = (v) => (v == null ? [] : Array.isArray(v) ? v : [v]);
162	const fill = (tpl, vars) => tpl.replace(/\{(\w+)\}/g, (whole, key) => (key in vars ? String(vars[key]) : whole));
163	const excluded = (path, exclude) =>
164	  exclude != null && (exclude instanceof RegExp ? exclude.test(path) : path === exclude);
165	
166	function relevant(ctx, when) {
167	  if (!when) return true;
168	  if (when.pathExists && !ctx.exists(when.pathExists)) return false;
169	  if (when.pathAbsent && ctx.exists(when.pathAbsent)) return false;
170	  if (when.trackedFileMatches && !ctx.tracked.some((f) => when.trackedFileMatches.test(f))) return false;
171	  if (when.noTrackedFileMatches && ctx.tracked.some((f) => when.noTrackedFileMatches.test(f))) return false;
172	  if (when.exactlyOneTrackedFileMatches &&
173	      ctx.tracked.filter((f) => when.exactlyOneTrackedFileMatches.test(f)).length !== 1) return false;
174	  if (when.someTrackedFileContains &&
175	      !ctx.tracked.some((f) => when.someTrackedFileContains.pathMatching.test(f) &&
176	        when.someTrackedFileContains.text.test(ctx.read(f) ?? ''))) return false;
177	  if (when.scanningWholeRepo && ctx.mode !== 'all') return false;
178	  return true; // repoContains resolves after the pass, and only when findings exist
179	}
