181	// --- markdown-section machinery (checkSections) ------------------------------
182	
183	const MD_BULLET = /^[-*+]\s/;
184	const MD_DATED = /^[-*+]\s+(?:\*\*)?(\d{4})-(\d{2})-(\d{2})(?:\*\*)?\b/;
185	const MD_CONTINUATION = /^\s+\S/;
186	const DAY_MS = 86_400_000;
187	const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
188	
189	// Date.UTC rolls out-of-range parts over (2026-02-30 → March 2) instead of
190	// failing, so calendar validity needs the explicit round-trip.
191	function realDateUTC(y, mo, d) {
192	  const dt = new Date(Date.UTC(y, mo - 1, d));
193	  return dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d
194	    ? dt.getTime() : null;
195	}
196	
197	// One parse of a page's section structure, shared by every subscribing rule:
198	// fenced lines blanked (count preserved, so line numbers never shift), the
199	// first `## ` heading, and each named section's body ({ line, text } entries,
200	// 1-indexed) memoized per name.
201	function markdownIndex(text) {
202	  let inFence = false;
203	  const stripped = text.split('\n').map((l) => {
204	    if (/^\s*(```|~~~)/.test(l)) { inFence = !inFence; return ''; }
205	    return inFence ? '' : l;
206	  });
207	  const firstLine = stripped.find((l) => /^##\s/.test(l));
208	  const sections = new Map();
209	  return {
210	    firstHeading: firstLine === undefined ? null : firstLine.replace(/^##\s+/, '').trim(),
211	    section(name) {
212	      const key = name.toLowerCase();
213	      if (!sections.has(key)) {
214	        const re = new RegExp(`^##\\s+${escapeRe(name)}\\b`, 'i');
215	        const start = stripped.findIndex((l) => re.test(l));
216	        if (start === -1) sections.set(key, null);
217	        else {
218	          let end = stripped.length;
219	          for (let i = start + 1; i < stripped.length; i++) {
220	            if (/^##\s/.test(stripped[i])) { end = i; break; }
221	          }
222	          sections.set(key, stripped.slice(start + 1, end).map((t, i) => ({ line: start + 2 + i, text: t })));
223	        }
224	      }
225	      return sections.get(key);
226	    },
227	  };
228	}
229	
230	function assertSections(ctx, j, path, md) {
231	  const excerpt = (s) => s.trim().slice(0, 80);
232	  const push = (a, at, vars) => j.out.push(finding(j.rule, {
233	    file: path, ...(at === null ? {} : { line: at }), what: fill(a.what, vars), fix: fill(a.fix, vars),
234	  }));
235	
236	  for (const entry of j.spec.checkSections) {
237	    for (const name of entry.sections ?? [entry.section]) {
238	      const body = md().section(name);
239	      const vars = { section: name };
240	      if (body === null) {
241	        if (entry.requirePresent) push(entry.requirePresent, null, vars);
242	        continue;
243	      }
244	
245	      if (entry.requireFirstOnPage) {
246	        const first = md().firstHeading;
247	        if (first !== null && !new RegExp(`^${escapeRe(name)}\\b`, 'i').test(first)) {
248	          push(entry.requireFirstOnPage, null, { ...vars, first });
249	        }
250	      }
251	
252	      let bullets = 0;
253	      const dated = [];
254	      const now = ctx.now ?? Date.now();
255	      for (let i = 0; i < body.length; i++) {
256	        const { line, text: t } = body[i];
257	        if (!MD_BULLET.test(t)) {
258	          if (entry.forbidProseLines && t.trim() !== '' && !MD_CONTINUATION.test(t)) {
259	            push(entry.forbidProseLines, line, { ...vars, line: excerpt(t) });
260	          }
261	          continue;
262	        }
263	        bullets += 1;
264	        const m = MD_DATED.exec(t);
265	        if (entry.eachBulletLeadsWithDate) {
266	          if (!m) push(entry.eachBulletLeadsWithDate.whenUndated, line, { ...vars, bullet: excerpt(t) });
267	          else if (realDateUTC(+m[1], +m[2], +m[3]) === null) {
268	            push(entry.eachBulletLeadsWithDate.whenNotRealDate, line, { ...vars, date: `${m[1]}-${m[2]}-${m[3]}` });
269	          }
270	        }
271	        if (entry.newestDatedBulletWithinDays && m) {
272	          const ts = realDateUTC(+m[1], +m[2], +m[3]);
273	          if (ts !== null && ts <= now + 2 * DAY_MS) dated.push(ts);
274	        }
275	        if (entry.eachBulletBlockMatches || entry.maxBulletBlockLength) {
276	          let block = t;
277	          for (let k = i + 1; k < body.length && MD_CONTINUATION.test(body[k].text); k++) {
278	            block += ` ${body[k].text.trim()}`;
279	          }
280	          if (entry.eachBulletBlockMatches && !entry.eachBulletBlockMatches.pattern.test(block)) {
281	            push(entry.eachBulletBlockMatches, line, { ...vars, bullet: excerpt(t) });
282	          }
283	          if (entry.maxBulletBlockLength && block.trim().length > entry.maxBulletBlockLength.characters) {
284	            push(entry.maxBulletBlockLength, line, { ...vars, bullet: excerpt(t), characters: block.trim().length });
285	          }
286	        }
287	      }
288	
289	      if (entry.minBullets && bullets < entry.minBullets.count) {
290	        push(entry.minBullets, null, { ...vars, bullets });
291	      } else if (entry.maxBullets && bullets > entry.maxBullets.count) {
292	        push(entry.maxBullets, null, { ...vars, bullets });
293	      }
294	
295	      if (entry.newestDatedBulletWithinDays && dated.length) {
296	        const a = entry.newestDatedBulletWithinDays;
297	        const newest = Math.max(...dated);
298	        const age = Math.floor(((ctx.now ?? Date.now()) - newest) / DAY_MS);
299	        if (age > a.days) {
300	          push(a, null, { ...vars, age, days: a.days, date: new Date(newest).toISOString().slice(0, 10) });
301	        }
302	      }
303	    }
304	  }
305	}
