307	const fieldAt = (doc, path) =>
308	  path.split('.').reduce((v, key) => (v && typeof v === 'object' ? v[key] : undefined), doc);
309	
310	function globToRe(glob) {
311	  return new RegExp(
312	    `^${glob.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\?/g, '.')}$`
313	  );
314	}
