316	// The tree/index assertions — they match paths and read at most one index file,
317	// so they run directly per rule rather than riding the content pass.
318	function assertTreeShape(ctx, j) {
319	  const s = j.spec;
320	  for (const a of s.requirePaths ?? []) {
321	    if (ctx.exists(a.path)) continue;
322	    const vars = { path: a.path };
323	    j.out.push(finding(j.rule, { file: a.path, what: fill(a.what, vars), fix: fill(a.fix, vars) }));
324	  }
325	
326	  for (const a of s.listedInFile ?? []) {
327	    const list = ctx.read(a.listFile);
328	    if (list === null) continue;
329	    const missing = new Map();
330	    for (const path of ctx.tracked) {
331	      const m = a.eachTrackedPathMatching.exec(path);
332	      if (!m) continue;
333	      const vars = { path, ...(m.groups ?? {}) };
334	      const token = fill(a.asText, vars);
335	      if (!missing.has(token) && !list.includes(token)) missing.set(token, vars);
336	    }
337	    for (const [, vars] of [...missing].sort(([t1], [t2]) => t1.localeCompare(t2))) {
338	      j.out.push(finding(j.rule, { file: a.listFile, what: fill(a.what, vars), fix: fill(a.fix, vars) }));
339	    }
340	  }
341	
342	  for (const a of s.coveredByGlobLine ?? []) {
343	    const globs = (ctx.read(a.globFile) ?? '').split('\n')
344	      .filter((line) => a.globLineMatching.test(line) && !line.trim().startsWith('#'))
345	      .map((line) => globToRe(line.trim().split(/\s+/)[0]));
346	    for (const path of a.includeVendored ? ctx.allFiles : ctx.files) {
347	      const m = a.eachPathMatching.exec(path);
348	      if (!m) continue;
349	      const base = path.slice(path.lastIndexOf('/') + 1);
350	      if (globs.some((re) => re.test(path) || re.test(base))) continue;
351	      const vars = { path, ...(m.groups ?? {}) };
352	      j.out.push(finding(j.rule, { file: path, what: fill(a.what, vars), fix: fill(a.fix, vars) }));
353	    }
354	  }
355	}
356	
357	// The structured-data assertions — they read a few named or tracked documents
358	// through the scan's shared parse cache, so like the tree assertions they run
359	// directly per rule rather than riding the content pass.
360	function assertParsedShape(ctx, j, parsed) {
361	  const s = j.spec;
362	
363	  for (const a of s.checkParsedFile ?? []) {
364	    const doc = parsed(a.file);
365	    if (doc == null) continue;
366	    if (a.whenFieldPresent && fieldAt(doc, a.whenFieldPresent) === undefined) continue;
367	    if (a.forbidField ? fieldAt(doc, a.forbidField) !== undefined
368	      : fieldAt(doc, a.requireField) === undefined) {
369	      j.out.push(finding(j.rule, { file: a.file, what: a.what, fix: a.fix }));
370	    }
371	  }
372	
373	  for (const a of s.equalParsedValues ?? []) {
374	    const firstPath = a.first.file ?? ctx.tracked.find((f) =>
375	      a.first.filesMatching.test(f) && a.first.whereFileContains.test(ctx.read(f) ?? ''));
376	    if (!firstPath) continue;
377	    const firstDoc = parsed(firstPath);
378	    if (firstDoc == null) continue;
379	    if (ctx.read(a.second.file) === null) {
380	      j.out.push(finding(j.rule, { file: a.second.file, what: a.whenSecondMissing.what, fix: a.whenSecondMissing.fix }));
381	      continue;
382	    }
383	    const secondDoc = parsed(a.second.file);
384	    if (secondDoc == null) continue;
385	    const vars = { first: fieldAt(firstDoc, a.first.field), second: fieldAt(secondDoc, a.second.field) };
386	    if (vars.first !== vars.second) {
387	      j.out.push(finding(j.rule, {
388	        file: firstPath, what: fill(a.whenUnequal.what, vars), fix: fill(a.whenUnequal.fix, vars),
389	      }));
390	    }
391	  }
392	
393	  for (const a of s.forEachParsedEntry ?? []) {
394	    for (const path of ctx.tracked) {
395	      if (!a.inFilesMatching.test(path)) continue;
396	      const entries = fieldAt(parsed(path), a.entriesAtField);
397	      if (!entries || typeof entries !== 'object' || Array.isArray(entries)) continue;
398	      for (const [name, entry] of Object.entries(entries)) {
399	        if (!entry || typeof entry !== 'object') continue;
400	        if (a.whereFieldEquals && fieldAt(entry, a.whereFieldEquals.field) !== a.whereFieldEquals.equals) continue;
401	        const values = fieldAt(entry, a.forbidValueInArray.atField);
402	        if (!Array.isArray(values)) continue;
403	        const norm = (v) => (a.forbidValueInArray.ignoreCase ? String(v).toLowerCase() : String(v));
404	        if (!values.some((v) => norm(v) === norm(a.forbidValueInArray.value))) continue;
405	        const vars = { entry: name, path };
406	        j.out.push(finding(j.rule, { file: path, what: fill(a.what, vars), fix: fill(a.fix, vars) }));
407	      }
408	    }
409	  }
410	
411	  for (const a of s.checkKeyValueFile ?? []) {
412	    const keysVar = { keys: a.keys.join(', ') };
413	    const text = ctx.read(a.file);
414	    if (text === null) {
415	      j.out.push(finding(j.rule, { file: a.file, what: fill(a.whenMissing.what, keysVar), fix: fill(a.whenMissing.fix, keysVar) }));
416	      continue;
417	    }
418	    const seen = new Set();
419	    text.split('\n').forEach((raw, i) => {
420	      const line = raw.trim();
421	      if (!line || line.startsWith('#')) return;
422	      const eq = line.indexOf('=');
423	      if (eq === -1) {
424	        const vars = { ...keysVar, line };
425	        j.out.push(finding(j.rule, { file: a.file, line: i + 1, what: fill(a.whenLineNotKeyValue.what, vars), fix: fill(a.whenLineNotKeyValue.fix, vars) }));
426	        return;
427	      }
428	      const key = line.slice(0, eq).trim();
429	      if (!a.keys.includes(key)) {
430	        const vars = { ...keysVar, key };
431	        j.out.push(finding(j.rule, { file: a.file, line: i + 1, what: fill(a.whenKeyUnknown.what, vars), fix: fill(a.whenKeyUnknown.fix, vars) }));
432	      }
433	      seen.add(key);
434	    });
435	    for (const key of a.keys) {
436	      if (seen.has(key)) continue;
437	      const vars = { ...keysVar, key };
438	      j.out.push(finding(j.rule, { file: a.file, what: fill(a.whenKeyMissing.what, vars), fix: fill(a.whenKeyMissing.fix, vars) }));
439	    }
440	  }
441	}
442	
443	// One file visited once for every subscribing rule: whole-text assertions and
444	// repo-wide bookkeeping first, then a single walk of the lines shared by all
445	// the rules' line assertions.
446	function visit(ctx, subs, path, text) {
447	  let split = null;
448	  const lines = () => (split ??= text.split('\n'));
449	  let mdIndex = null;
450	  const md = () => (mdIndex ??= markdownIndex(text));
451	  const lineJobs = [];
452	
453	  for (const j of subs) {
454	    const s = j.spec;
455	    if (s.checkSections) assertSections(ctx, j, path, md);
456	    if (s.maxLines && lines().length > s.maxLines.limit) {
457	      const vars = { lines: lines().length, limit: s.maxLines.limit };
458	      j.out.push(finding(j.rule, {
459	        file: path, line: s.maxLines.limit + 1,
460	        what: fill(s.maxLines.what, vars), fix: fill(s.maxLines.fix, vars),
461	      }));
462	    }
463	    for (const a of s.checkEachFile ?? []) {
464	      if (a.relevantWhen && !relevant(ctx, a.relevantWhen)) continue;
465	      if (!arr(a.whenFileMatches).every((re) => re.test(text))) continue;
466	      if (a.forbid ? a.forbid.test(text) : !a.require.test(text)) {
467	        j.out.push(finding(j.rule, { file: path, what: a.what, fix: a.fix }));
468	      }
469	    }
470	    for (const st of j.repoStates) {
471	      if (st.a.unlessSomeFileMatches.test(text)) st.satisfied = true;
472	      if (excluded(path, st.a.neverFlagFiles)) continue;
473	      const group = st.a.flagFilesMatching.find((g) => g.every((re) => re.test(text)));
474	      if (group) {
475	        const at = lines().findIndex((ln) => group[0].test(ln));
476	        st.hits.push({ file: path, line: at === -1 ? null : at + 1, what: st.a.what, fix: st.a.fix });
477	      }
478	    }
479	    const eligible = (s.matchLines ?? []).filter((a) =>
480	      arr(a.whenFileMatches).every((re) => re.test(text)) && !a.unlessFileMatches?.test(text));
481	    if (eligible.length) lineJobs.push({ j, eligible });
482	  }
483	
484	  if (!lineJobs.length) return;
485	  lines().forEach((ln, i) => {
486	    for (const { j, eligible } of lineJobs) {
487	      if (j.spec.skipLinesMatching?.test(ln)) continue;
488	      for (const a of eligible) {
489	        const m = ln.match(a.match);
490	        if (!m || a.unlessLineMatches?.test(ln)) continue;
491	        const vars = { match: m[0] };
492	        j.out.push(finding(j.rule, {
493	          file: path, line: i + 1, what: fill(a.what, vars), fix: fill(a.fix, vars),
494	        }));
495	        break;
496	      }
497	    }
498	  });
499	}
500	
501	function results(ctx) {
502	  let res = scans.get(ctx);
503	  if (res) return res;
504	  res = new Map();
505	  scans.set(ctx, res);
506	
507	  const jobs = [];
508	  for (const rule of REGISTRY) {
509	    const out = [];
510	    res.set(rule, out);
511	    if (!relevant(ctx, rule.spec.relevantWhen)) continue;
512	    jobs.push({
513	      rule, spec: rule.spec, out,
514	      repoStates: (rule.spec.repoWide ?? []).map((a) => ({ a, satisfied: false, hits: [] })),
515	    });
516	  }
517	
518	  const parsedDocs = new Map();
519	  const parsed = (path) => {
520	    if (!parsedDocs.has(path)) {
521	      const text = ctx.read(path);
522	      let doc = null;
523	      if (text !== null) {
524	        if (/\.ya?ml$/.test(path)) doc = parseYaml(text);
525	        else { try { doc = JSON.parse(text); } catch { doc = null; } }
526	      }
527	      parsedDocs.set(path, doc);
528	    }
529	    return parsedDocs.get(path);
530	  };
531	
532	  for (const j of jobs) {
533	    assertTreeShape(ctx, j);
534	    assertParsedShape(ctx, j, parsed);
535	    if (typeof j.spec.scanFiles !== 'string') continue;
536	    const text = ctx.read(j.spec.scanFiles);
537	    if (text === null) {
538	      if (j.spec.whenMissing) {
539	        j.out.push(finding(j.rule, { file: j.spec.scanFiles, what: j.spec.whenMissing.what, fix: j.spec.whenMissing.fix }));
540	      }
541	      continue;
542	    }
543	    visit(ctx, [j], j.spec.scanFiles, text);
544	  }
545	
546	  const swept = jobs.filter((j) => j.spec.scanFiles instanceof RegExp);
547	  if (swept.length) {
548	    const scanned = new Set(ctx.files);
549	    const tracked = new Set(ctx.tracked);
550	    for (const path of [...ctx.files, ...ctx.tracked.filter((f) => !scanned.has(f))]) {
551	      const subs = swept.filter((j) =>
552	        (j.spec.scanTracked ? tracked : scanned).has(path) &&
553	        j.spec.scanFiles.test(path) && !excluded(path, j.spec.excludeFiles));
554	      if (!subs.length) continue;
555	      const text = ctx.read(path);
556	      if (text !== null) visit(ctx, subs, path, text);
557	    }
558	  }
559	
560	  for (const j of jobs) {
561	    for (const st of j.repoStates) {
562	      if (!st.satisfied) for (const h of st.hits) j.out.push(finding(j.rule, h));
563	    }
564	    const marker = j.spec.relevantWhen?.repoContains;
565	    if (marker && j.out.length &&
566	        !ctx.files.some((f) => !excluded(f, j.spec.excludeFiles) && marker.test(ctx.read(f) ?? ''))) {
567	      j.out.length = 0;
568	    }
569	  }
570	  return res;
571	}
572	
573	// Where a declaration says RegExp: keys reading `/body/flags` strings. The two
574	// sets differ in what a NON-regex string means — a path at PATH_OR_PATTERN_KEYS
575	// (scanFiles: "README.md" is read directly), an authoring error anywhere else.
576	const PATH_OR_PATTERN_KEYS = new Set(['scanFiles', 'excludeFiles']);
577	const PATTERN_KEYS = new Set([
578	  'skipLinesMatching', 'match', 'unlessLineMatches', 'whenFileMatches', 'unlessFileMatches',
579	  'require', 'forbid', 'trackedFileMatches', 'noTrackedFileMatches', 'exactlyOneTrackedFileMatches',
580	  'pathMatching', 'text', 'repoContains', 'unlessSomeFileMatches', 'flagFilesMatching',
581	  'neverFlagFiles', 'eachTrackedPathMatching', 'eachPathMatching', 'globLineMatching',
582	  'filesMatching', 'whereFileContains', 'inFilesMatching', 'pattern',
583	]);
584	const RE_FORM = /^\/(.*)\/([dgimsuvy]*)$/s;
585	
586	// Compile a spec's pattern strings in place of their keys, leaving every other
587	// value (paths, field names, failure text, numbers) exactly as declared. A real
588	// RegExp passes through, so a spec built in code — the engine's own tests — is
589	// the same object either way.
590	function compileSpec(value, key, where) {
591	  if (Array.isArray(value)) return value.map((v) => compileSpec(v, key, where));
592	  if (value === null || value instanceof RegExp) return value;
593	  if (typeof value === 'string') {
594	    if (!PATTERN_KEYS.has(key) && !PATH_OR_PATTERN_KEYS.has(key)) return value;
595	    const form = RE_FORM.exec(value);
596	    if (!form) {
597	      if (PATH_OR_PATTERN_KEYS.has(key)) return value;
598	      throw new Error(`${where}: "${key}" takes a regex in /pattern/flags form, not ${JSON.stringify(value)}`);
599	    }
600	    try { return new RegExp(form[1], form[2]); }
601	    catch (e) { throw new Error(`${where}: "${key}" is not a valid regex — ${e.message}`); }
602	  }
603	  if (typeof value !== 'object') return value;
604	  const out = {};
605	  for (const [k, v] of Object.entries(value)) out[k] = compileSpec(v, k, where);
606	  return out;
607	}
608	
609	export function patternRule(declaration) {
610	  const spec = compileSpec(declaration, null, `the declared check "${declaration.id}"`);
611	  const rule = {
612	    id: spec.id,
613	    severity: spec.severity,
614	    why: spec.failureMessage,
615	    spec,
616	    run(ctx) { return results(ctx).get(rule); },
617	  };
618	  REGISTRY.push(rule);
619	  return rule;
620	}
621	
622	// A directory's declared checks: `<dir>/declared-checks.json`, an array of specs
623	// compiled into rules — none when the file is absent. Cached by path, so the
624	// registry and a test asking the same directory share one set of rule objects
625	// (two would each re-run the shared scan for the same assertions).
626	const loaded = new Map();
627	export function loadDeclaredChecks(dir) {
628	  const path = join(dir, 'declared-checks.json');
629	  if (!loaded.has(path)) {
630	    let specs = [];
631	    if (existsSync(path)) {
632	      let raw;
633	      try { raw = JSON.parse(readFileSync(path, 'utf8')); }
634	      catch (e) { throw new Error(`${path} is not valid JSON: ${e.message}`); }
635	      if (!Array.isArray(raw)) throw new Error(`${path} must be an array of check declarations`);
636	      specs = raw;
637	    }
638	    loaded.set(path, specs.map(patternRule));
639	  }
640	  return loaded.get(path);
641	}
