1	#!/usr/bin/env node
2	// World-scope conformance runner (see DESIGN.md): the rules that audit repo
3	// state as it exists now, plus the pack-agnostic settings/load integrity
4	// diagnostics (malformed config, an unknown pack, a broken pack.mjs). Rules that
5	// judge the current change (`scope: 'work'`) run in check_the_work.mjs, which
6	// this file shares no code with — only the scope-blind mechanism helpers
7	// (run-active-pack-rules.mjs, report-findings.mjs). It names NO pack: adoption
8	// interview hygiene is a skill-owned check that rides its own pack's activation,
9	// and a malformed `questions` field is a load fault the pack registry reports.
10	// Wired into the project's test/CI flow, not the Stop hook. Dependency-free Node ≥18.
11	//   (default)   whole-repo sweep — milliseconds on a text corpus, sees cross-file breakage
12	//   --changed   transitional: scope to files changed vs the merge-base with main
13	//               (adopting a repo with a backlog only — not the enforcement default)
14	//   --base REF  override the base ref
15	//   --list      machine-readable catalog of every rule, both scopes (id, severity, description, doc)
16	//   --init      write .claudinite-checks.json — basics plus the fingerprinted packs
17	import { writeFileSync, existsSync } from 'node:fs';
18	import { join } from 'node:path';
19	import { buildContext } from './helpers/repo-context.mjs';
20	import { discoverPacks, resolveDeclaredPacks } from '../pack_loader/pack-registry.mjs';
21	import { runActivePackRules, packRules } from './run-active-pack-rules.mjs';
22	import { reportFindings } from './report-findings.mjs';
23	
24	const configError = (what, fix) => ({
25	  rule: 'config', severity: 'blocking', file: '.claudinite-checks.json', line: null,
26	  what, why: 'the settings file is what executes — a bad key, value, or pack name silently changes what runs', fix, doc: 'engine/checks/README.md',
27	});
28	
29	const args = process.argv.slice(2);
30	const has = (flag) => args.includes(flag);
31	const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
32	// The repo to sweep. `--root` first, then CLAUDE_PROJECT_DIR, and only then the cwd.
33	// The env var is not a convenience: the callers that run this from inside a converge
34	// (the update runner) have a cwd that no longer exists — the vendor step deletes
35	// `.claudinite/shared/`, which is where prework's cwd lives — and `process.cwd()` then
36	// throws `ENOENT … uv_cwd` before a single check runs, which reads from the outside as
37	// "this mount has no checks" (#689). engine/selftest.mjs has always resolved its root
38	// this way; this closes the disagreement for every caller, not just that one.
39	const root = value('--root') || process.env.CLAUDE_PROJECT_DIR || process.cwd();
40	
41	if (has('--list')) {
42	  const { packs } = await discoverPacks({ localRoot: root });
43	  for (const r of packRules(packs)) {
44	    // A declared check carries neither a description nor a doc pointer — it
45	    // states its own case — so the catalog prints its failure message in that
46	    // column and leaves the pointer empty.
47	    console.log(`${r.id}\t${r.severity}\t${r.description ?? r.why ?? ''}\t${r.doc ?? ''}`);
48	  }
49	  process.exit(0);
50	}
51	
52	if (has('--init')) {
53	  const path = join(root, '.claudinite-checks.json');
54	  if (existsSync(path)) {
55	    console.log(`${path} already exists — leaving it as-is.`);
56	    process.exit(0);
57	  }
58	  const { packs } = await discoverPacks({ localRoot: root });
59	  const ctx = buildContext({ root, mode: 'all' });
60	  // No pack is active by default, so the baseline is seeded as an explicit
61	  // declaration alongside the fingerprinted packs: every pack that flags
62	  // `seededByDefault` is written in (discovered structurally — the engine names
63	  // no pack), plus the ones a fingerprint detects. A seeded pack is still
64	  // opt-out-able where its own policy allows (the update flows re-add only the packs
65	  // whose absence it treats as drift), so removing a seeded declaration can
66	  // stick; each seeded pack ships its own one-time seed migration for the fleet.
67	  // Local packs are declared by hand, never fingerprinted or seeded — exclude
68	  // them from --init's seeding so a repo that already carries local packs (but
69	  // no config yet) doesn't auto-declare them.
70	  const seeded = packs.filter((p) => p.seededByDefault && !p.local).map((p) => p.id);
71	  const detected = [...seeded, ...packs.filter((p) => p.detect && !p.local && p.detect(ctx)).map((p) => p.id)];
72	  // A pack can't be imported without its dependencies — pull each declared pack's
73	  // `requires` closure into the declaration so it's complete and visible.
74	  const declared = resolveDeclaredPacks(detected, packs);
75	  // maintenance.delivery is deliberately materialized, not defaulted — the selection
76	  // must be visible in the file where a project would change it (see engine/checks/README.md).
77	  // Only what carries a decision: the declaration and the always-explicit
78	  // delivery. Empty rules/accept boilerplate is noise, not settings (#385);
79	  // loadConfig defaults absent keys.
80	  writeFileSync(path, `${JSON.stringify({ packs: declared, maintenance: { delivery: 'auto-merge' } }, null, 2)}\n`);
81	  console.log(`Wrote ${path} (packs: ${declared.join(', ')}).`);
82	  // The adoption interview (surfacing each declared pack's pending questions) is
83	  // driven by the adopt-claudinite skill / bootstrap.md, and nudged every session
84	  // by the SessionStart interview-check step — not printed here, so this runner
85	  // imports no pack.
86	  process.exit(0);
87	}
88	
89	const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
90	const ctx = buildContext({ root, mode: has('--changed') ? 'changed' : 'all', baseOverride: value('--base') });
91	
92	// Settings/load integrity — pack-agnostic, so the world runner owns them.
93	// Settings validity is checked at load: malformed JSON, an unknown
94	// property, and a wrong pack name are all equally settings errors. loadConfig
95	// reports the first two; the runner adds unknown pack names (only it holds the
96	// registry) and broken/duplicate local pack.mjs faults.
97	const findings = [];
98	for (const e of ctx.config.errors) findings.push(configError(e.what, e.fix));
99	for (const e of packErrors) findings.push(configError(e.what, e.fix));
100	// knownIds spans canon AND local packs, so a declared local pack id is valid and
101	// the unknown-pack message lists it among the declarable packs. ctx.config.packs
102	// is loadConfig's normalized view — bare ids, a namespaced local_packs/<name>
103	// declaration already resolved through packEntryId.
104	const knownIds = new Set(packs.map((p) => p.id));
105	for (const name of ctx.config.packs) {
106	  if (typeof name === 'string' && !knownIds.has(name)) {
107	    findings.push(configError(`declares unknown pack "${name}"`, `remove it or fix the name — declarable packs: ${[...knownIds].sort().join(', ')}`));
108	  }
109	}
110	// (Adoption-interview hygiene is a skill-owned check that runs below with the
111	// other active-pack rules; a malformed `questions` field arrives as a load fault
112	// in packErrors above. Neither names a pack here.)
113	
114	// The world rules: everything not scoped to the work. A broken contributedRules
115	// seam is a config-level fault surfaced here (the world runner owns diagnostics).
116	findings.push(...runActivePackRules(ctx, packs, {
117	  includeRule: (rule) => rule.scope !== 'work',
118	  onContributeError: (pack, e) => findings.push(configError(
119	    `the "${pack.id}" pack's contributedRules failed: ${e.message}`, 'fix the pack manifest, or the contribution it interprets')),
120	}));
121	
122	const blocking = reportFindings(findings, ctx.config, { scopeLabel: 'world', mode: ctx.mode, baseRef: ctx.baseRef });
123	process.exit(blocking ? 1 : 0);
124

