588	// RegExp passes through, so a spec built in code — the engine's own tests — is
589	// the same object either way.
590	function compileSpec(value, key, where) {
591	  if (Array.isArray(value)) return value.map((v) => compileSpec(v, key, where));
592	  if (value === null || value instanceof RegExp) return value;
593	  if (typeof value === 'string') {
594	    if (!PATTERN_KEYS.has(key) && !PATH_OR_PATTERN_KEYS.has(key)) return value;
595	    const form = RE_FORM.exec(value);
596	    if (!form) {
