546	        : null;
547	    if (toRaw === null) {
548	      errors.push({ what: `${at} needs a "to" folder path (or an array of them), or a "between" pair`, fix: 'add a "to" folder path, or use "between": [a, b]' });
549	      return;
550	    }
551	    const targets = toRaw.map(parseTarget);
552	    if (targets.includes(null)) return;
553	    if (targets.includes('*') && targets.length > 1) {
554	      errors.push({ what: `${at}: "*" cannot be combined with other "to" entries`, fix: 'isolation ("*") already bars everything — drop the other entries or the "*"' });
555	      return;
556	    }
557	    const edge = mk(froms, targets);
558	    const prob = edgeProblem(edge, at);
559	    if (prob) { errors.push(prob); return; }
560	    edges.push(edge);
561	  });
562	  return { edges, errors };
563	}
564	
565	// --- reviewed-exception filtering (per edge) --------------------------------
566	
567	// Filter one edge's crossing findings through its reviewed exceptions. Returns
568	// the survivors plus the stale (path, to) pairs — exceptions that matched no
569	// crossing, meaning the coupling they excused is gone and the entry should be
570	// pruned. A `to`-less exception excuses every crossing from its file; a pinned
571	// one only crossings landing under a named barred folder, per to-entry.
572	function applyExceptions(findings, exceptions) {
573	  const used = exceptions.map((e) => (e.to ? e.to.map(() => false) : [false]));
574	  const kept = findings.filter((f) => {
575	    for (let i = 0; i < exceptions.length; i++) {
576	      const e = exceptions[i];
577	      if (!(e.path === f.file || (e.path.endsWith('/') && f.file.startsWith(e.path)))) continue;
578	      if (!e.to) { used[i][0] = true; return false; }
579	      for (let j = 0; j < e.to.length; j++) {
580	        if (under(f.resolved, e.to[j])) { used[i][j] = true; return false; }
581	      }
582	    }
583	    return true;
584	  });
585	  const stale = [];
586	  exceptions.forEach((e, i) => {
587	    if (!e.to) { if (!used[i][0]) stale.push({ path: e.path, to: null }); }
588	    else e.to.forEach((t, j) => { if (!used[i][j]) stale.push({ path: e.path, to: t }); });
589	  });
590	  return { kept, stale };
591	}
592	
593	// --- the scan ---------------------------------------------------------------
594	
595	const escRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
596	
597	// Run the given edges over the context. Returns { findings, stale }: the crossing
598	// findings that survive each edge's reviewed exceptions, plus the stale exception
599	// pairs the caller may surface as prune-me findings (gated on a whole-repo sweep).
600	// `rule` supplies id / severity / doc. Every crossing finding carries the resolved
601	// path as `resolved`; config-shape findings (empty glob) do not.
602	export function barrierFindings(ctx, edges, rule) {
603	  if (!edges.length) return { findings: [], stale: [] };
604	  const index = buildIndex(ctx);
605	  const scannable = ctx.files.map((f) => f.replace(/\\/g, '/')).filter((f) => !isTestFile(f));
606	  const out = [];
607	  const staleAll = [];
608	  const readCache = new Map();
609	  const read = (f) => {
610	    if (!readCache.has(f)) readCache.set(f, ctx.read(f));
611	    return readCache.get(f);
612	  };
613	  const childDirs = (p) => [...index.dirs].filter((d) => d.startsWith(`${p}/`) && !d.slice(p.length + 1).includes('/'));
614	
615	  const scanEdge = (edge) => {
616	    const carve = edge.carve.flatMap((e) => (isGlob(e) ? childDirs(globPrefix(e)) : [e]));
617	    const star = edge.targets.includes('*');
618	    const barred = [];
619	    let broken = false;
620	    for (const t of edge.targets) {
621	      if (t === '*') continue;
622	      if (isGlob(t)) {
623	        const kids = childDirs(globPrefix(t));
624	        if (!kids.length) {
625	          // Structural enumeration came up empty — fail closed, never silently
626	          // enforce nothing (a renamed folder must not disarm the barrier).
627	          out.push(specFinding(rule, {
628	            what: `"to" glob "${t}" matched no directories`,
629	            fix: 'check the folder exists and has tracked subdirectories — an empty expansion would enforce nothing',
630	          }));
631	          broken = true;
632	        }
633	        barred.push(...kids);
634	      } else barred.push(t);
635	    }
636	    if (broken) return;
637	
638	    const inGuard = (p) => edge.froms.some((fp) => under(p, fp)) && !carveMatch(p, carve);
639	
640	    // The names layer: an edge with `matchNames: true` also matches the bare
641	    // NAMES of its barred folders — but only distinctive ones (containing "-" or
642	    // "_"), which ordinary prose never produces, plus any the edge force-includes
643	    // via alsoMatchNames. This catches identifier-level coupling (a hardcoded
644	    // folder name in a string or doc) that no path ever spells out.
645	    let nameRe = null;
646	    const nameDirs = new Map();
647	    if (edge.matchNames) {
648	      const bases = new Map();
649	      for (const d of barred) {
650	        const base = d.slice(d.lastIndexOf('/') + 1);
651	        if (!bases.has(base)) bases.set(base, []);
652	        bases.get(base).push(d);
653	      }
654	      for (const [base, dirs] of bases) {
655	        if (/[-_]/.test(base) || edge.alsoMatchNames.includes(base)) nameDirs.set(base, dirs);
656	      }
657	      for (const n of edge.alsoMatchNames) {
658	        if (!bases.has(n)) {
659	          out.push(specFinding(rule, {
660	            what: `"alsoMatchNames" entry "${n}" is not the name of any barred folder`,
661	            fix: 'fix the name or drop the entry — it matches nothing',
662	          }));
663	        }
664	      }
665	      if (nameDirs.size) {
666	        nameRe = new RegExp(`(^|[^\\w./-])(${[...nameDirs.keys()].map(escRe).join('|')})(?=[^\\w./-]|$)`, 'g');
667	      }
668	    }
669	
670	    // The fix's leading clause: how to KEEP the dependency legitimately. The
671	    // default assumes a two-sided edge with somewhere shared to route through —
672	    // true for a project's own folder graph, false for a one-sided isolation
673	    // edge (nothing may reference the barred side at all, and its code is
674	    // often not ours to restructure). A rule whose remedy is something else
675	    // entirely — inline it, re-express it as declaration — overrides via
676	    // `crossingRemedy`, the same seam as `crossingExcuse` below. The finding
677	    // renders what/why/fix/doc and never the rule's `description`, so a remedy
678	    // that lives only in the description never reaches whoever trips the rule.
679	    const allowHint = rule.crossingRemedy
680	      || (edge.allow.length
681	        ? `route shared code through an allowed folder (${edge.allow.join(', ')})`
682	        : 'route shared code through a shared/contracts folder both sides may use');
683	    // A pack-shipped fixed barrier's edges are code, so "add a reviewed
684	    // exception" (per-rule except entries in the project's own config) cannot
685	    // resolve its findings — such a rule overrides the excusal clause via
686	    // `crossingExcuse` to point at the lever that actually works (an accept).
687	    const excuse = rule.crossingExcuse
688	      || 'add a reviewed exception in .claudinite-checks.json if the crossing is deliberate';
689	    const raw = [];
690	    const seen = new Set();
691	    const emit = (file, line, what, r) => {
692	      const key = `${file}:${line}:${r}`;
693	      if (seen.has(key)) return;
694	      seen.add(key);
695	      raw.push({
696	        ...finding(rule, {
697	          file,
698	          line,
699	          what,
700	          why: edge.reason || rule.why,
701	          fix: `${allowHint}, remove the reference, or ${excuse}`,
702	        }),
703	        resolved: r,
704	      });
705	    };
706	
707	    // An imports-scoped edge scans only code files, and only their relative
708	    // import/require specifiers, resolved as module edges (resolveImport) —
709	    // matchNames is validated away for it, so the names layer below never arms.
710	    const importsOnly = edge.scope === 'imports';
711	    const guarded = scannable.filter((f) => inGuard(f) && (!importsOnly || CODE_FILE.test(f)));
712	    for (const file of guarded) {
713	      const text = read(file);
714	      if (text === null) continue;
715	      const fromDir = file.includes('/') ? file.slice(0, file.lastIndexOf('/')) : '';
716	      if (importsOnly) {
717	        for (const { spec, line } of importSpecifiers(text)) {
718	          const r = resolveImport(spec, fromDir, index);
719	          if (r === null || inGuard(r)) continue;
720	          if (edge.allow.some((a) => under(r, a))) continue;
721	          const t = barred.find((b) => under(r, b));
722	          if (star) {
723	            emit(file, line, `imports "${spec}" → resolves to "${r}", outside the guarded region`, r);
724	          } else if (t) {
725	            emit(file, line, `imports "${spec}" → resolves to "${r}", inside the barred folder "${t}"`, r);
726	          }
727	        }
728	        continue;
729	      }
730	      const lines = text.split('\n');
731	      for (let i = 0; i < lines.length; i++) {
732	        for (const rawRef of candidatesOn(lines[i])) {
733	          const r = resolveRef(rawRef, fromDir, index, edge.matchUniqueFilenames);
734	          if (r === null || inGuard(r)) continue;
735	          if (edge.allow.some((a) => under(r, a))) continue;
736	          const t = barred.find((b) => under(r, b));
737	          if (star) {
738	            emit(file, i + 1, `references "${rawRef}" → resolves to "${r}", outside the guarded region`, r);
739	          } else if (t) {
740	            emit(file, i + 1, `references "${rawRef}" → resolves to "${r}", inside the barred folder "${t}"`, r);
741	          }
742	        }
743	        if (nameRe) {
744	          nameRe.lastIndex = 0;
745	          let m;
746	          while ((m = nameRe.exec(lines[i])) !== null) {
747	            for (const d of nameDirs.get(m[2])) {
748	              if (inGuard(d) || edge.allow.some((a) => under(d, a))) continue;
749	              emit(file, i + 1, `mentions "${m[2]}", the name of the barred folder "${d}"`, d);
750	            }
751	          }
752	        }
753	      }
754	    }
755	
756	    const { kept, stale } = applyExceptions(raw, edge.exceptions);
757	    out.push(...kept);
758	    staleAll.push(...stale);
759	  };
760	
761	  for (const edge of edges) {
762	    // A siblings edge expands against the real tree: each direct child
763	    // directory of the named folder becomes the guarded `from` of its own
764	    // sub-edge (so a child's own files pass via the self-reference rule while
765	    // every sibling stays barred). Fail closed on an empty expansion — a
766	    // renamed folder must not silently disarm the barrier.
767	    if (edge.siblings) {
768	      const kids = childDirs(edge.siblings);
769	      if (!kids.length) {
770	        out.push(specFinding(rule, {
771	          what: `"siblings" folder "${edge.siblings}" has no tracked child directories`,
772	          fix: 'check the folder exists and has tracked subdirectories — an empty expansion would enforce nothing',
773	        }));
774	        continue;
775	      }
776	      for (const kid of kids) scanEdge({ ...edge, froms: [kid] });
777	      continue;
778	    }
779	    scanEdge(edge);
780	  }
781	  return { findings: out, stale: staleAll };
782	}
783	
784	// Emit a spec/shape error as a blocking finding pinned at the settings file.
785	export function specFinding(rule, { what, fix }) {
786	  return finding(rule, {
787	    file: '.claudinite-checks.json',
788	    line: null,
789	    what: `barriers config: ${what}`,
790	    why: 'a malformed barrier declaration silently enforces nothing',
791	    fix,
792	    severity: 'blocking',
793	  });
794	}
795	
796	// A stale reviewed exception (it matched no crossing) means the coupling it
797	// excused is gone — surface it so paid-down debt gets pruned. Judged only by the
798	// caller on a whole-repo sweep with a clean config (a --changed run sees only
799	// part of the findings; a config error means the scan itself was incomplete).
800	export function staleFindings(stale, rule) {
801	  return stale.map((s) => specFinding(rule, {
802	    what: `exception for "${s.path}"${s.to ? ` → "${s.to}"` : ''} matched nothing — the coupling it excused is gone`,
803	    fix: `remove the stale exception${s.to ? ' (or the stale "to" item)' : ''} from the rule's "except"`,
804	  }));
805	}
806	
807

