import json, glob, collections
keys = collections.Counter()
rules = 0
msg_lens = []
for p in glob.glob('packs/*/declared-checks.json') + glob.glob('packs/*/skills/*/declared-checks.json'):
    for spec in json.load(open(p)):
        rules += 1
        for k in spec:
            if k not in ('id','severity','failureMessage'):
                keys[k] += 1
        def walk(o):
            if isinstance(o, dict):
                for k,v in o.items():
                    if k in ('what','fix','failureMessage') and isinstance(v,str):
                        msg_lens.append((len(v.split()), spec['id'], k))
                    walk(v)
            elif isinstance(o, list):
                for v in o: walk(v)
        walk(spec)
        msg_lens.append((len(spec['failureMessage'].split()), spec['id'], 'failureMessage'))
print('declared rules:', rules)
for k,c in keys.most_common(): print(f'{c:3} {k}')
msg_lens.sort(reverse=True)
print('\nlongest message fields (words):')
for n,rid,k in msg_lens[:12]: print(f'{n:4} {rid} .{k}')
import statistics
print('median words per message field:', statistics.median(n for n,_,_ in msg_lens))
EOF

