// Shared scanning surface for the jwt pack's skill checks — the file-set policy
// and the call-window walker every rule composes. Pack-local on purpose: the
// engine's helpers stay content-blind, while what counts as "a JWT source file"
// is exactly this pack's policy, stated once so five rules cannot drift on it.

// The languages the rules read. Tests and fixtures are excluded everywhere: a
// test hardcoding a secret or a forbidden algorithm list is exercising the
// hazard, not shipping it (the corpus's own fixtures ride this same exemption).
const SOURCE = /\.(mjs|cjs|js|jsx|ts|tsx|py)$/;
const TEST_PATH = /(^|\/)(tests?|__tests__|spec|fixtures)\/|\.(test|spec)\.[a-z]+$|_test\.py$/;
// This pack's own tree (canon checkout or vendored mount): rule modules and
// their tests quote the very patterns they hunt, so they never self-flag.
const PACK_SELF = /(^|\/)(packs|packs-tests)\/jwt\//;

// The in-scope files: project source, no tests, not this pack itself.
export function sourceFiles(ctx) {
  return ctx.files.filter((f) => SOURCE.test(f) && !TEST_PATH.test(f) && !PACK_SELF.test(f));
}

// Every call site in `text` whose opener matches `callRe` (a regex ending at
// the call's open paren), returned as { line, window }: the window runs from
// the match to the call's balanced closing paren, capped at 2000 chars so a
// pathological file cannot stall the sweep. Balance-counting ignores strings —
// a paren inside a literal can cut a window short, which only ever makes a
// rule QUIETER (a truncated window is judged against its whole file too).
export function callWindows(text, callRe) {
  const out = [];
  const re = new RegExp(callRe.source, callRe.flags.includes('g') ? callRe.flags : `${callRe.flags}g`);
  for (const m of text.matchAll(re)) {
    const open = text.indexOf('(', m.index);
    if (open === -1) continue;
    let depth = 0;
    let end = Math.min(text.length, open + 2000);
    for (let i = open; i < open + 2000 && i < text.length; i++) {
      if (text[i] === '(') depth++;
      else if (text[i] === ')' && --depth === 0) { end = i + 1; break; }
    }
    out.push({ line: text.slice(0, m.index).split('\n').length, window: text.slice(m.index, end) });
  }
  return out;
}
import hardcodedSecret from './hardcoded-secret.mjs';
import signSetsExpiry from './sign-sets-expiry.mjs';

// The check-the-world rules validating this skill's action — minting JWTs.
// Discovered by engine/pack_loader/pack-registry.mjs onto the jwt pack and run
// when it is active; each is inert until a token-minting artifact exists (its
// RELEVANCE FIRST gate). The failure messages carry the rules — there is
// deliberately no prose copy to drift from.
export default [hardcodedSecret, signSetsExpiry];
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { matchingLines } from '../../../../engine/checks/helpers/line-scanning.mjs';
import { sourceFiles } from '../../scan.mjs';

// A signing secret written as a string literal ships with every clone and
// lives in git history forever — and for HMAC algorithms, whoever reads it can
// MINT tokens, not just verify them. Repo-state on purpose: a committed secret
// stays compromised until rotated out, however long ago it merged.
//
// RELEVANCE FIRST: JS/TS files importing 'jsonwebtoken' (sign/verify's second
// argument is the key) and Python files importing jwt (encode/decode's second
// argument), then only lines passing a plain string literal in that position.
// A template literal with an interpolation (`${…}`) is config plumbing, not a
// hardcoded secret, and is skipped. Tests are excluded by the shared file-set
// policy — a fixture secret exercises the hazard rather than shipping it.
const JS = /\.(mjs|cjs|js|jsx|ts|tsx)$/;
const PY = /\.py$/;
const JSONWEBTOKEN = /['"]jsonwebtoken['"]/;
const PY_IMPORT = /^\s*(import\s+jwt\b|from\s+jwt(\.[\w.]*)?\s+import\b)/m;
const JS_LITERAL_KEY = /\.(sign|verify)\s*\(\s*[^,()]+,\s*(['"`])(?!\s*\2)[^'"`]+\2/;
const PY_LITERAL_KEY = /\bjwt\.(encode|decode)\s*\(\s*[^,()]+,\s*(['"])[^'"]+\2/;
const INTERPOLATED = /\$\{/;

const rule = {
  id: 'jwt-hardcoded-secret',
  severity: 'blocking',
  description: 'No JWT sign/verify call takes a literal string as its secret or key',
  doc: 'skills/jwt-minting/SKILL.md',
  why: 'a secret in source ships with every clone and survives in git history forever, and an HMAC secret grants full token-MINTING power to anyone who reads it',

  run(ctx) {
    const js = sourceFiles(ctx).filter((f) => JS.test(f) && JSONWEBTOKEN.test(ctx.read(f) ?? ''));
    const py = sourceFiles(ctx).filter((f) => PY.test(f) && PY_IMPORT.test(ctx.read(f) ?? ''));
    return [
      ...matchingLines(ctx, js, JS_LITERAL_KEY).filter(({ text }) => !INTERPOLATED.test(text)),
      ...matchingLines(ctx, py, PY_LITERAL_KEY),
    ].map(({ file, line }) => finding(rule, {
      file, line,
      what: 'passes a literal string as the JWT signing secret/key',
      fix: 'load the secret from the environment or a secret store, and make it >= 32 random bytes (RFC 7518: an HMAC key at least as long as the hash output) — then rotate the committed one',
    }));
  },
};

export default rule;
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { sourceFiles, callWindows } from '../../scan.mjs';

// A token minted with no exp is valid forever: stateless validation has no
// revocation, so a leaked non-expiring token is a permanent credential. The
// static signature is a sign/encode call with no expiry in sight.
//
// Advisory on purpose: some tokens legitimately never expire (a device pairing
// blob), and the payload may be assembled in another file — so this is a smell
// to judge. RELEVANCE FIRST: JS/TS importing 'jsonwebtoken' (`.sign(` sites,
// expiry = the expiresIn option or an exp claim) and Python importing jwt
// (`jwt.encode(` sites, expiry = an exp claim); the word appearing anywhere in
// the file passes it, the same benefit-of-the-doubt fallback the pinning rule
// uses.
const JS = /\.(mjs|cjs|js|jsx|ts|tsx)$/;
const PY = /\.py$/;
const JSONWEBTOKEN = /['"]jsonwebtoken['"]/;
const PY_IMPORT = /^\s*(import\s+jwt\b|from\s+jwt(\.[\w.]*)?\s+import\b)/m;
const EXPIRY = /\bexpiresIn\b|\bexp\b/;

const rule = {
  id: 'jwt-sign-sets-expiry',
  severity: 'advisory',
  description: 'A minted JWT carries an expiry (expiresIn option or exp claim)',
  doc: 'skills/jwt-minting/SKILL.md',
  why: 'a token with no exp never stops being valid, and stateless validation has no revocation — a leak becomes a permanent credential',

  run(ctx) {
    const out = [];
    const sites = [
      { files: sourceFiles(ctx).filter((f) => JS.test(f)), lib: JSONWEBTOKEN, call: /\.sign\s*\(/ },
      { files: sourceFiles(ctx).filter((f) => PY.test(f)), lib: PY_IMPORT, call: /\bjwt\.encode\s*\(/ },
    ];
    for (const { files, lib, call } of sites) {
      for (const f of files) {
        const text = ctx.read(f) ?? '';
        if (!lib.test(text) || EXPIRY.test(text)) continue;
        for (const { line } of callWindows(text, call)) {
          out.push(finding(rule, {
            file: f, line,
            what: 'signs a JWT with no expiry in sight (no expiresIn option or exp claim in this file)',
            fix: 'set expiresIn (or an exp claim) when signing, as short as the flow allows — pair long-lived access with a refresh token, not a long expiry',
          }));
        }
      }
    }
    return out;
  },
};

export default rule;

