import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { matchingLines } from '../../../../engine/checks/helpers/line-scanning.mjs';
import { sourceFiles } from '../../scan.mjs';

// The alg:none bypass: strip a token's signature, set the header's alg to
// "none", and a verifier that honors it accepts attacker-written claims as
// valid. The one static signature of honoring it is "none" sitting in an
// algorithms allowlist — jsonwebtoken's `algorithms: [...]`, PyJWT's
// `algorithms=[...]`. Repo-state on purpose: a pre-existing allowlist with
// "none" is a live bypass and must keep firing until fixed.
//
// RELEVANCE FIRST (engine/checks/README.md "Adding a rule"): only non-test
// JS/TS/Python source that references a JWT surface at all, then only lines
// carrying the allowlist-with-none shape. Test paths and this pack's own tree
// are excluded by the shared file-set policy (scan.mjs).
const JWT_HINT = /jwt|jose/i;
const NONE_IN_LIST = /\balgorithms?\s*[:=]\s*\[[^\]]*['"]none['"]/i;

const rule = {
  id: 'jwt-none-not-accepted',
  severity: 'blocking',
  description: 'No JWT verification algorithm allowlist accepts "none"',
  doc: 'skills/jwt-validation/SKILL.md',
  why: 'a token whose header claims alg "none" carries no signature at all, so a verifier that accepts it treats attacker-written claims as authenticated — the classic signature-stripping bypass',

  run(ctx) {
    const files = sourceFiles(ctx).filter((f) => JWT_HINT.test(ctx.read(f) ?? ''));
    return matchingLines(ctx, files, NONE_IN_LIST).map(({ file, line }) => finding(rule, {
      file, line,
      what: 'lists "none" in a JWT verification-algorithm allowlist',
      fix: 'remove "none" — an unsigned token must never verify; list only the exact algorithm(s) this verifier expects',
    }));
  },
};

export default rule;
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { sourceFiles, callWindows } from '../../scan.mjs';

// Substitution attacks: a signature only proves who SIGNED a token, never who
// it was FOR — a valid token minted for another service (or another context in
// the same service) passes a verifier that checks nothing but the signature.
// Binding the expected audience (and issuer) at the verify call is what scopes
// a token to this consumer.
//
// Advisory on purpose: a single-party token (signer == only verifier, e.g. a
// client-side session blob) legitimately skips aud/iss, so this is a smell to
// judge, not a defect to fix. RELEVANCE FIRST: JS/TS source importing
// 'jsonwebtoken' or 'jose', then only verify call sites; the word appearing
// anywhere in the file (an options object built elsewhere) passes it.
const LIB = /['"](jsonwebtoken|jose)['"]/;
const JS = /\.(mjs|cjs|js|jsx|ts|tsx)$/;
const VERIFY_CALL = /\.verify\s*\(|\bjwtVerify\s*\(/;
const BOUND = /\b(audience|issuer)\b/;

const rule = {
  id: 'jwt-verify-binds-audience',
  severity: 'advisory',
  description: 'A JWT verify call binds the expected audience or issuer',
  doc: 'skills/jwt-validation/SKILL.md',
  why: 'the signature proves who signed the token, not who it was for — without an audience/issuer check, a valid token minted for a different service or purpose is accepted here (substitution attack)',

  run(ctx) {
    const out = [];
    for (const f of sourceFiles(ctx).filter((x) => JS.test(x))) {
      const text = ctx.read(f) ?? '';
      if (!LIB.test(text) || BOUND.test(text)) continue;
      for (const { line } of callWindows(text, VERIFY_CALL)) {
        out.push(finding(rule, {
          file: f, line,
          what: 'verifies a JWT binding neither audience nor issuer (neither word appears in this file)',
          fix: 'pass the expected audience (and issuer) to the verify call so a token minted for another recipient is rejected — validate every claim the token carries',
        }));
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { sourceFiles, callWindows } from '../../scan.mjs';

// With no algorithms allowlist, jsonwebtoken historically selected the
// verification algorithm from the token's own header — the attacker-controlled
// field — enabling both the alg:none bypass and the RS256-public-key-as-HS256-
// secret forgery. Explicit pinning closes the whole class, whatever the library
// version's defaults.
//
// RELEVANCE FIRST: only JS/TS source that imports 'jsonwebtoken' (the one
// library with this exact call shape; jose binds algorithms to key types),
// then only `.verify(` call sites. A call whose window lacks `algorithms` gets
// the benefit of the doubt when the WORD appears anywhere else in the file
// (an options object built above the call) — the same file-level fallback the
// google-token-audience rule uses to stay false-positive-free.
const JSONWEBTOKEN = /['"]jsonwebtoken['"]/;
const JS = /\.(mjs|cjs|js|jsx|ts|tsx)$/;
const VERIFY_CALL = /\.verify\s*\(/;
const ALGORITHMS = /\balgorithms\b/;

const rule = {
  id: 'jwt-verify-pins-algorithms',
  severity: 'blocking',
  description: 'Every jsonwebtoken verify call pins an explicit algorithms allowlist',
  doc: 'skills/jwt-validation/SKILL.md',
  why: 'without an allowlist the verification algorithm can come from the token\'s own header — the attacker writes that header, so they pick the algorithm ("none", or HS256 keyed with your published public key)',

  run(ctx) {
    const out = [];
    for (const f of sourceFiles(ctx).filter((x) => JS.test(x))) {
      const text = ctx.read(f) ?? '';
      if (!JSONWEBTOKEN.test(text) || ALGORITHMS.test(text)) continue;
      for (const { line } of callWindows(text, VERIFY_CALL)) {
        out.push(finding(rule, {
          file: f, line,
          what: 'verifies a JWT with no algorithms allowlist (and none is set anywhere in this file)',
          fix: 'pass { algorithms: [\'<the one algorithm this issuer uses>\'] } to every jsonwebtoken verify call — never let the token pick',
        }));
      }
    }
    return out;
  },
};

export default rule;
import noneNotAccepted from './none-not-accepted.mjs';
import verifyPinsAlgorithms from './verify-pins-algorithms.mjs';
import verifyBindsAudience from './verify-binds-audience.mjs';

// The check-the-world rules validating this skill's action — wiring JWT
// verification. Discovered by engine/pack_loader/pack-registry.mjs onto the jwt
// pack and run when it is active; each is inert until a JWT verification
// artifact exists (its RELEVANCE FIRST gate). The failure messages carry the
// rules — there is deliberately no prose copy to drift from.
export default [noneNotAccepted, verifyPinsAlgorithms, verifyBindsAudience];

