231	// A remote-tracking base ref goes stale the moment the base branch moves, and a cloud
232	// session's clone freezes it at container-creation time. Everything the base gained since
233	// then sits in `mergeBase..HEAD` and gets billed to the work — squash-merge-history (a
234	// blocking rule) reporting other people's merge commits as introduced by this change.
235	test('buildContext: a stale remote base ref is refreshed, so the base branch\'s own merges are not the work\'s', () => {
236	  const origin = mkdtempSync(join(tmpdir(), 'claudinite-origin-'));
237	  git(origin, 'init', '-q', '-b', 'main');
238	  writeFiles(origin, { 'README.md': 'seed\n' });
239	  git(origin, 'add', '-A');
240	  git(origin, 'commit', '-q', '-m', 'seed');
241	
242	  const root = mkdtempSync(join(tmpdir(), 'claudinite-clone-'));
243	  rmSync(root, { recursive: true, force: true });
244	  git(process.cwd(), 'clone', '-q', origin, root); // origin/main pinned at seed
245	
246	  // The base branch advances — including a merge commit — after the clone.
247	  git(origin, 'checkout', '-q', '-b', 'side');
248	  writeFiles(origin, { 's.txt': 'x\n' });
249	  git(origin, 'add', '-A');
250	  git(origin, 'commit', '-q', '-m', 'side work');
251	  git(origin, 'checkout', '-q', 'main');
252	  git(origin, 'merge', '-q', '--no-ff', '-m', 'merge side', 'side');
253	
254	  // The session's branch is cut from the *current* base tip, while the clone's
255	  // origin/main still points at the seed: fetched under its own ref name so the
256	  // explicit refspec leaves origin/main untouched, exactly as the real clone was.
257	  git(root, 'fetch', '-q', origin, '+refs/heads/main:refs/remotes/snapshot/main');
258	  git(root, 'checkout', '-q', '-B', 'feature', 'snapshot/main');
259	  writeFiles(root, { 'w.txt': 'x\n' });
260	  git(root, 'add', '-A');
261	  git(root, 'commit', '-q', '-m', 'my work Refs #1');
262	
263	  try {
264	    // Opted out of the refresh: the stale ref is believed, and the base branch's
265	    // merge is misread as introduced here — the bug, pinned.
266	    process.env.CLAUDINITE_CHECKS_NO_FETCH = '1';
267	    const stale = buildContext({ root, mode: 'changed' });
268	    assert.deepEqual(stale.introducedMergeCommits().map((m) => m.subject), ['merge side']);
269	
270	    // Default: the ref is refreshed first, so the merge is where it belongs — on the
271	    // base branch, out of the work's range.
272	    delete process.env.CLAUDINITE_CHECKS_NO_FETCH;
273	    const fresh = buildContext({ root, mode: 'changed' });
274	    assert.deepEqual(fresh.introducedMergeCommits(), []);
275	  } finally {
276	    delete process.env.CLAUDINITE_CHECKS_NO_FETCH;
277	    cleanup(root);
278	    cleanup(origin);
279	  }
