    "id": "jwt-none-not-accepted",
    "severity": "blocking",
    "failureMessage": "a token whose header claims alg \"none\" carries no signature at all, so a verifier that accepts it treats attacker-written claims as authenticated — the classic signature-stripping bypass",
    "scanFileClasses": ["javascriptFiles", "pythonFiles"],
    "excludeFileClasses": ["testFiles"],
    "matchLines": [
      {
        "match": "/\\balgorithms?\\s*[:=]\\s*\\[[^\\]]*['\"]none['\"]/i",
        "whenFileMatches": "/jwt|jose/i",
        "what": "lists \"none\" in a JWT verification-algorithm allowlist",
        "fix": "remove \"none\" — an unsigned token must never verify; list only the exact algorithm(s) this verifier expects"
      }
    ]
  },
  {
    "id": "jwt-verify-pins-algorithms",
    "severity": "blocking",
    "failureMessage": "without an allowlist the verification algorithm can come from the token's own header — the attacker writes that header, so they pick the algorithm (\"none\", or HS256 keyed with your published public key)",
    "scanFileClasses": ["javascriptFiles"],
    "excludeFileClasses": ["testFiles"],
    "matchLines": [
      {
        "match": "/\\.verify\\s*\\(/",
        "whenFileMatches": "/['\"]jsonwebtoken['\"]/",
        "unlessFileMatches": "/\\balgorithms\\b/",
        "what": "verifies a JWT with no algorithms allowlist (and none is set anywhere in this file)",
        "fix": "pass { algorithms: ['<the one algorithm this issuer uses>'] } to every jsonwebtoken verify call — never let the token pick"
      }
    ]
  },
  {
    "id": "jwt-verify-binds-audience",
    "severity": "advisory",
    "failureMessage": "the signature proves who signed the token, not who it was for — without an audience/issuer check, a valid token minted for a different service or purpose is accepted here (substitution attack)",
    "scanFileClasses": ["javascriptFiles"],
    "excludeFileClasses": ["testFiles"],
    "matchLines": [
      {
        "match": "/\\.verify\\s*\\(|\\bjwtVerify\\s*\\(/",
        "whenFileMatches": "/['\"](jsonwebtoken|jose)['\"]/",
        "unlessFileMatches": "/\\b(audience|issuer)\\b/",
        "what": "verifies a JWT binding neither audience nor issuer (neither word appears in this file)",
        "fix": "pass the expected audience (and issuer) to the verify call so a token minted for another recipient is rejected — validate every claim the token carries"
      }
    ]
  }
]

[
  {
    "id": "product-wiki-page-sections",
    "severity": "blocking",
    "failureMessage": "the sections are the page's reader header plus the wiki's audit trail and backlog — without them compile-once/refine-in-place degrades to unsourced, unreviewable rewrites nobody can read at a glance",
    "scanFiles": "/^product-wiki\\/.+\\/README\\.md$/",
    "excludeFiles": "/^product-wiki\\/(product-requirements|sample-data)\\//",
    "checkSections": [
      {
        "sections": ["Key insights", "Sources", "Growth log", "Open questions"],
        "requirePresent": {
          "what": "wiki page is missing its \"## {section}\" section",
          "fix": "add it — every wiki page opens with the Key insights header, then carries the growth machinery: the citations list, the dated growth log, and the open-questions backlog (an empty \"## Open questions\" is valid)"
        }
      }
    ]
  },
  {
    "id": "product-wiki-key-insights",
    "severity": "blocking",
    "failureMessage": "a research page whose findings can only be recovered by reading it end to end does not get read — the header is what makes a compiled wiki usable to a human",
    "scanFiles": "/^product-wiki\\/.+\\/README\\.md$/",
    "excludeFiles": "/^product-wiki\\/(product-requirements|sample-data)\\//",
    "checkSections": [
      {
        "section": "Key insights",
        "requireFirstOnPage": {
          "what": "the page opens with \"## {first}\", not its \"## Key insights\" header",
          "fix": "move \"## Key insights\" above every other section — a header a reader reaches after the body is not a header"
        },
        "forbidProseLines": {
          "what": "prose in the Key insights header: \"{line}\"",
          "fix": "the header is a bulleted list only — make it a bullet or move it into the page body below the \"## Key insights\" section"
        },
        "maxBulletBlockLength": {
          "characters": 140,
          "what": "Key insights bullet runs {characters} characters (max 140): \"{bullet}…\"",
          "fix": "cut it to the finding in plain words — the qualifiers, the supporting detail and the citation all live in the page body"
        },
        "minBullets": {
          "count": 1,
          "what": "Key insights header carries no bullets",
          "fix": "open the page with \"## Key insights\" — up to 7 bullets, each one finding stated plainly in a line (max 140 characters), together enough for a reader to understand what the research found without reading the body"
        },
        "maxBullets": {
          "count": 7,
          "what": "Key insights header carries {bullets} bullets (max 7) — it has grown into a second body",
          "fix": "keep the 7 that matter most; the rest is what the page body is for"
        }
      }
    ]
  },
  {
    "id": "product-wiki-growth-log",
    "severity": "blocking",
    "failureMessage": "undated or absent log entries break the audit trail and the freshness signal every other growth mechanism keys on",
    "scanFiles": "/^product-wiki\\/.+\\/README\\.md$/",
    "excludeFiles": "/^product-wiki\\/(product-requirements|sample-data)\\//",
    "checkSections": [
      {
        "section": "Growth log",
        "eachBulletLeadsWithDate": {
          "whenUndated": {
            "what": "growth-log entry does not lead with its date: \"{bullet}\"",
            "fix": "lead every growth-log bullet with the run date, e.g. \"- **2026-07-15** — what changed\"; append the seed entry when the page is first committed"
          },
          "whenNotRealDate": {
            "what": "growth-log entry \"{date}\" is not a real calendar date",
            "fix": "lead every growth-log bullet with the run date, e.g. \"- **2026-07-15** — what changed\"; append the seed entry when the page is first committed"
          }
        },
        "minBullets": {
          "count": 1,
          "what": "growth log has no dated entries",
          "fix": "lead every growth-log bullet with the run date, e.g. \"- **2026-07-15** — what changed\"; append the seed entry when the page is first committed"
        }
      }
    ]
  },
  {
    "id": "product-wiki-sources",
    "severity": "blocking",
    "failureMessage": "a named source without its URL is an uncited citation — unverifiable by the next pass and by review",
    "scanFiles": "/^product-wiki\\/.+\\/README\\.md$/",
    "excludeFiles": "/^product-wiki\\/(product-requirements|sample-data)\\//",
    "checkSections": [
      {
        "section": "Sources",
        "eachBulletBlockMatches": {
          "pattern": "/https?:\\/\\//",
          "what": "Sources bullet carries no URL: \"{bullet}\"",
          "fix": "every listed source carries its real URL (a markdown link or a bare URL); an honestly-unsourced page explains its status in prose instead of listing URL-less sources"
        }
      }
    ]
  },
  {
    "id": "product-wiki-freshness",
    "severity": "advisory",
    "failureMessage": "a wiki that stopped growing silently stops being true — staleness must reach a human even when the unattended growth channel isn't firing",
    "relevantWhen": { "scanningWholeRepo": true },
    "scanFiles": "/^product-wiki\\/.+\\/README\\.md$/",
    "excludeFiles": "/^product-wiki\\/(product-requirements|sample-data)\\//",
    "checkSections": [
      {
        "section": "Growth log",
        "newestDatedBulletWithinDays": {
          "days": 45,
          "what": "newest Growth log entry is {age} days old ({date}) — past the {days}-day freshness window",
          "fix": "run a product-wiki growth pass (in-session: \"grow the product wiki\"; method: the canon's packs/product-wiki/tasks/wiki-growth/task.md, mounted under .claudinite/ in consumers), or confirm this repo's scheduler workflow is wired and the wiki-growth task is on its schedule; silence via rules: {\"product-wiki-freshness\": \"off\"}"
        }
      }
    ]
  }
]

