import {
  normalizeEdges, barrierFindings, staleFindings, specFinding, DEFAULT_DOC,
} from './engine.mjs';

// The project-declared barrier check: a repo states its folder-access graph as
// `config.rules` on its barriers pack entry in .claudinite-checks.json (the
// loader overlays each pack entry's `config` onto `packConfig`), and this
// enforces it. A rule owns its exceptions — carve-out strings and reviewed
// { path, to?, reason } crossings both live in the rule's own `except`, so a NEW
// coupling in an already-reviewed file still fails and paid-down debt goes stale.
// (A pack that ships a *fixed* barrier uses engine.mjs `defineBarrier` instead and
// adds it to its own `rules`.)
const rule = {
  id: 'barrier',
  severity: 'blocking',
  doc: DEFAULT_DOC,
  description: "Folders must not reference across a declared barrier (the barriers pack entry's config)",
  why: 'a declared folder barrier encodes an architectural boundary; a crossing reference erodes it silently',

  run(ctx) {
    const cfg = ctx.config?.packConfig?.barriers;
    if (cfg === undefined || cfg === null) return []; // declared but unconfigured — nothing to enforce
    if (typeof cfg !== 'object' || Array.isArray(cfg) || !('rules' in cfg)) {
      return [specFinding(rule, {
        what: 'the barriers config must be an object with a "rules" array',
        fix: 'set { "packs": [ { "id": "barriers", "config": { "rules": [ { "from": "...", "to": "..." } ] } } ] }',
      })];
    }
    const out = [];
    const unknown = Object.keys(cfg).filter((k) => k !== 'rules');
    if (unknown.length) {
      out.push(specFinding(rule, {
        what: `the barriers config has unknown ${unknown.length > 1 ? 'properties' : 'property'} ${unknown.map((k) => `"${k}"`).join(', ')} — exceptions live per-rule now, in each rule's "except"`,
        fix: 'it takes only "rules"; move accept/except entries into the owning rule\'s "except"',
      }));
    }
    const { edges, errors } = normalizeEdges(cfg.rules);
    out.push(...errors.map((e) => specFinding(rule, e)));

    const { findings, stale } = barrierFindings(ctx, edges, rule);
    out.push(...findings);

    // Staleness is trustworthy only on a whole-repo sweep with a clean config: a
    // --changed run sees only part of the findings, and any config/scan error
    // means the scan was incomplete.
    const scanErrors = findings.some((f) => f.resolved === undefined);
    if (ctx.mode === 'all' && !unknown.length && !errors.length && !scanErrors) {
      out.push(...staleFindings(stale, rule));
    }
    return out;
  },
};

export default rule;

import { PRODUCT_ROOT, SINK_DIR } from './lib.mjs';

// The wall: nothing outside product-wiki/ may reference the self-growing wiki
// folders; product-wiki/product-requirements is the one reviewed crossing point.
// A CONTRIBUTED barrier: this module is pure data the barriers pack builds into
// the rule (product-wiki `requires` barriers and carries this under
// `contributes` on its manifest — the declaration-and-configuration composition
// pack-independence mandates). This edge and product-wiki-layout are a designed
// pair — the glob target fails closed ("matched no directories", blocking) on an
// empty product-wiki/ expansion, and layout owns the missing-skeleton complaint.
// Under the structural standard a renamed wiki folder is still a wiki folder,
// still barred — no per-folder disarm hole.
//
// Edge notes (each empirically verified against a real consumer tree):
// - to 'product-wiki/*' bars every direct CHILD DIRECTORY of product-wiki/; files
//   directly under product-wiki/ (the index README) stay reachable — a repo's root
//   CLAUDE.md legitimately links product-wiki/README.md.
// - allow keeps the crossing point reachable from every guarded file.
// - except 'product-wiki' unguards the whole product-wiki/ subtree (wikis reference
//   each other, sample-data, and outward freely — the wall is one-directional)
//   and satisfies the root-guard validation for the glob target.
// - except '.claudinite-checks.json': the settings file legitimately spells
//   wiki paths (accept entries, historical config) — configuration is not a
//   dependency.
// - matchUniqueFilenames OFF: wiki/sample-data filenames are agent-written,
//   so leaving the unique-basename layer on would let every distinctive
//   filename the growth routine invents become a repo-wide barred bare name
//   outside the consumer's review. Path references still fire.
// - No baked reviewed-exceptions, and consumers can't add any to a
//   pack-shipped edge — crossingExcuse points each finding at the lever that
//   works (an accept; see packs/product-wiki/README.md). Unlike a rule-owned
//   except, accepts are not staleness-audited — prune them by hand.
export default {
  id: 'product-wiki-isolation',
  description: 'Nothing outside product-wiki/ may reference the self-growing wiki folders — product-wiki/product-requirements is the only crossing point',
  why: 'the wikis are agent-rewritten, loosely-sourced research — code, tests, and docs that silently depend on them inherit unreviewed churn',
  doc: 'packs/product-wiki/README.md',
  crossingExcuse: 'if the crossing is deliberate, excuse it with accept: [{ "rule": "product-wiki-isolation", "path": "<file>", "reason": "..." }] in .claudinite-checks.json (a pack-shipped barrier takes no per-rule except entries — see packs/product-wiki/README.md)',
  edges: [{
    from: '.',
    to: `${PRODUCT_ROOT}/*`,
    allow: [SINK_DIR],
    matchUniqueFilenames: false,
    except: [PRODUCT_ROOT, '.claudinite-checks.json'],
    reason: 'the self-growing product wikis and their sample data are autonomous research the repo must not depend on; product-wiki/product-requirements is the one reviewed crossing point',
  }],
};

// Pack independence — as BARRIERS CONFIGURATION, not code. A pack's code
// imports only its OWN files and the engine surface; another pack's abilities
// arrive by DECLARING the dependency (`requires` on the pack manifest) and
// passing configuration, and a helper both sides need moves into engine/checks/helpers.
// A cross-pack import crashes every consumer that vendors the importer without
// its target (the vendor set ships a pack only when declared, and ships no
// canon-internal tree at all) — the failure the gated vendored-mount flip
// aborts on.
//
// This module is pure DATA: the barriers pack builds it into the rule
// (canon-curation `requires` barriers and carries this under `contributes` on
// its manifest — the same declaration-and-configuration composition the rule
// itself mandates; no code here checks anything). The `siblings` edge guards
// each pack under packs/ in turn; `to: "*"` confines it to itself plus the
// engine surface in `allow`; `scope: "imports"` keeps the ban on the coupling
// class that crashes — code imports — while prose stays free to talk about
// packs. The `allow` list IS the engine surface — the one always-vendored
// engine/ root (#385); a new surface root would join it here, loudly — the
// barrier fails closed, never silently widens. The vendor
// writer's coherence guard (vendoring/compute-vendor-set.mjs) backstops the same invariant at
// vendoring time.
//
// Home-only twice over: declared solely by the canon home (a contributed rule
// runs only where its contributor is active), and `gateDir` keeps it inert
// anywhere a packs/ tree doesn't exist.
export default {
  id: 'pack-independence',
  description: 'A pack\'s code imports only its own files and the engine surface — another pack\'s abilities arrive through declaration (requires) and configuration, never by importing its code',
  why: 'the vendor set ships a pack only when declared, so a cross-pack import crashes every consumer that vendors one pack without the other; abilities cross pack boundaries through declaration and configuration',
  doc: 'extending.md',
  crossingExcuse: 'if the crossing is deliberate, excuse it with accept: [{ "rule": "pack-independence", "path": "<file>", "reason": "..." }] in .claudinite-checks.json (a pack-shipped barrier takes no per-rule except entries)',
  gateDir: 'packs',
  edges: [{
    siblings: 'packs',
    to: '*',
    scope: 'imports',
    allow: [
      'engine',
    ],
    reason: 'a pack imports only its own files and the engine surface — declare the dependency and pass configuration (a contributed rule), or move the shared helper into engine/checks/helpers',
  }],
};

