+// Emit a spec/shape error as a blocking finding pinned at the settings file.
+export function specFinding(rule, { what, fix }) {
+  return finding(rule, {
+    file: '.claudinite-checks.json',
+    line: null,
+    what: `barriers config: ${what}`,
